package com.example.eventy.common;

import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.drawable.BitmapDrawable;
import android.graphics.drawable.Drawable;
import android.util.Base64;

import java.io.ByteArrayOutputStream;

public class PictureHelperService {
    public final static String defaultProfilePicture = "data:image/png;base64,";
    public final static String defaultOrganizerProfilePicture = "data:image/png;base64,";
    // UBACITI OVO (iz back-a): resources/static/event_organiser_profile_picture.png
    public final static String defaultProviderProfilePicture = "data:image/png;base64,";
    // UBACITI OVO (iz back-a): resources/static/solution_provider_profile_picture.png

    public static Bitmap getPicture(String base64string) {
        if (base64string == null || base64string.isEmpty()) {
            return null;
        }

        if (base64string.contains(",")) {
            base64string = base64string.split(",")[1];
        }

        byte[] imageBytes = Base64.decode(base64string, Base64.DEFAULT);

        return BitmapFactory.decodeByteArray(imageBytes, 0, imageBytes.length);
    }

    public static Drawable getPicture(String base64Image, Context context) {
        if (base64Image == null || base64Image.isEmpty()) {
            base64Image = defaultProfilePicture;
        }

        try {
            // remove the "data:image/png;base64," prefix if it exists
            if (base64Image.contains(",")) {
                base64Image = base64Image.split(",")[1];
            }

            byte[] decodedBytes = Base64.decode(base64Image, Base64.DEFAULT);
            Bitmap bitmap = BitmapFactory.decodeByteArray(decodedBytes, 0, decodedBytes.length);

            // Convert Bitmap to Drawable
            return new BitmapDrawable(context.getResources(), bitmap);

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String bitmapToBase64(Bitmap bitmap) {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        bitmap.compress(Bitmap.CompressFormat.PNG, 100, outputStream); // Use PNG or JPEG
        byte[] byteArray = outputStream.toByteArray();
        return "data:image/png;base64," + Base64.encodeToString(byteArray, Base64.NO_WRAP);
    }
}
